import pathlib
import subprocess
import sys
import tempfile
import unittest

import pysam


SCRIPT = pathlib.Path(__file__).resolve().parents[1] / "bam_rename.py"


class BamRenameTests(unittest.TestCase):
    def test_reads_embedded_reference_cram_directly(self):
        with tempfile.TemporaryDirectory() as temp_dir:
            root = pathlib.Path(temp_dir)
            reference = root / "reference.fasta"
            reference.write_text(">tig00000001\nACGTACGT\n")
            pysam.faidx(str(reference))

            header = {
                "HD": {"VN": "1.6"},
                "SQ": [{"SN": "tig00000001", "LN": 8}],
                "RG": [{"ID": "LA"}, {"ID": "LAO"}, {"ID": "UL"}],
            }
            source = root / "part.cram"
            with pysam.AlignmentFile(
                source,
                "wc",
                header=header,
                reference_filename=str(reference),
                format_options=[b"embed_ref=1"],
            ) as output:
                read = pysam.AlignedSegment(output.header)
                read.query_name = "hifi_read1"
                read.query_sequence = "ACGT"
                read.flag = 0
                read.reference_id = 0
                read.reference_start = 0
                read.mapping_quality = 60
                read.cigarstring = "4M"
                read.query_qualities = pysam.qualitystring_to_array("IIII")
                read.set_tag("RG", "LAO")
                output.write(read)

                gap_read = pysam.AlignedSegment(output.header)
                gap_read.query_name = "ont_gap"
                gap_read.query_sequence = "ACGT"
                gap_read.flag = 0
                gap_read.reference_id = 0
                gap_read.reference_start = 4
                gap_read.mapping_quality = 60
                gap_read.cigarstring = "4M"
                gap_read.query_qualities = pysam.qualitystring_to_array("IIII")
                gap_read.set_tag("RG", "UL")
                output.write(gap_read)
            pysam.index(str(source))

            layout = root / "layout"
            layout.write_text("hifi_read1\t0\t4\t1\nont_gap\t4\t8\t1\n")
            gaps = root / "gaps"
            gaps.write_text("ont_gap\tgap\n")
            scfmap = root / "scfmap"
            scfmap.write_text("path\tscaffold1\tpath1\npiece000001\nend\n")
            tigmap = root / "tigmap"
            tigmap.write_text("1\tpiece000001\n")
            consensus = root / "part.fasta"
            consensus.write_text(">tig00000001\nACGTACGT\n")
            renamed = root / "renamed.bam"

            with renamed.open("wb") as output:
                subprocess.run(
                    [
                        sys.executable,
                        str(SCRIPT),
                        str(layout),
                        str(gaps),
                        str(scfmap),
                        str(tigmap),
                        str(consensus),
                        "--alignments",
                        str(source),
                    ],
                    check=True,
                    stdout=output,
                )

            with pysam.AlignmentFile(renamed, "rb") as result:
                self.assertEqual(("scaffold1",), result.references)
                records = list(result)
                self.assertEqual(("LA", "LAO", "UL", "UL-gap"), tuple(group["ID"] for group in result.header.to_dict()["RG"]))
            self.assertEqual(2, len(records))
            self.assertEqual("read1", records[0].query_name)
            self.assertEqual(0, records[0].reference_start)
            self.assertEqual("LAO", records[0].get_tag("RG"))
            self.assertEqual("gap", records[1].query_name)
            self.assertEqual(4, records[1].reference_start)
            self.assertEqual("UL-gap", records[1].get_tag("RG"))


if __name__ == "__main__":
    unittest.main()
